#include <stdio.h>
#include <stdlib.h>

/* ---------- fast input ---------- */
static unsigned char ibuf[1 << 16];
static int ilen = 0, ipos = 0;

static int gc(void) {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt(void) {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9') && c != '-') c = gc();
    if (c == -1) return 0;
    int neg = 0;
    if (c == '-') { neg = 1; c = gc(); }
    long long x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return neg ? -x : x;
}

/* ---------- heaps (lazy deletion) ---------- */
static long long *PR;   /* price of objects (grouped by type) */
static int *TP;         /* type of objects */
static char *SOLD;      /* 1 if object already sold */

/* mode 0: compare by price only (per-type heaps)
   mode 1: compare by (price, type) (global heap) */
static inline int better(int a, int b, int mode) {
    if (PR[a] != PR[b]) return PR[a] < PR[b];
    if (mode) return TP[a] < TP[b];
    return 0;
}

static void sift_down(int *hp, int size, int idx, int mode) {
    for (;;) {
        int l = idx * 2 + 1;
        if (l >= size) break;
        int b = l;
        int r = l + 1;
        if (r < size && better(hp[r], hp[b], mode)) b = r;
        if (better(hp[b], hp[idx], mode)) {
            int tmp = hp[idx]; hp[idx] = hp[b]; hp[b] = tmp;
            idx = b;
        } else break;
    }
}

static void build_heap(int *hp, int size, int mode) {
    for (int i = size / 2 - 1; i >= 0; i--) sift_down(hp, size, i, mode);
}

static int heap_pop(int *hp, int *psize, int mode) {
    int top = hp[0];
    int size = *psize - 1;
    hp[0] = hp[size];
    *psize = size;
    if (size > 0) sift_down(hp, size, 0, mode);
    return top;
}

int main(void) {
    int N = (int)readInt();
    int T = (int)readInt();

    size_t nbuf = (size_t)(N > 0 ? N : 1);
    int *t = malloc(sizeof(int) * nbuf);
    int *p = malloc(sizeof(int) * nbuf);
    for (int i = 0; i < N; i++) t[i] = (int)readInt();
    for (int i = 0; i < N; i++) p[i] = (int)readInt();
    int C = (int)readInt();

    /* group objects by type into contiguous segments */
    int *cnt = calloc((size_t)T + 2, sizeof(int));
    for (int i = 0; i < N; i++) cnt[t[i]]++;

    int *start = malloc(sizeof(int) * (size_t)(T + 2));
    int acc = 0;
    for (int tt = 1; tt <= T; tt++) { start[tt] = acc; acc += cnt[tt]; }

    PR = malloc(sizeof(long long) * nbuf);
    TP = malloc(sizeof(int) * nbuf);
    SOLD = calloc(nbuf, 1);

    int *fill = malloc(sizeof(int) * (size_t)(T + 2));
    for (int tt = 1; tt <= T; tt++) fill[tt] = start[tt];
    for (int i = 0; i < N; i++) {
        int q = fill[t[i]]++;
        PR[q] = p[i];
        TP[q] = t[i];
    }

    /* per-type min-heaps (one segment each) and global min-heap */
    int *H = malloc(sizeof(int) * nbuf);
    int *GH = malloc(sizeof(int) * nbuf);
    for (int q = 0; q < N; q++) { H[q] = q; GH[q] = q; }

    for (int tt = 1; tt <= T; tt++)
        if (cnt[tt] > 1) build_heap(H + start[tt], cnt[tt], 0);
    if (N > 0) build_heap(GH, N, 1);

    int gsize = N;
    long long total = 0;

    for (int j = 0; j < C; j++) {
        int uj = (int)readInt();
        if (uj == 0) {
            /* undecided customer: min (price, type) globally */
            while (gsize > 0 && SOLD[GH[0]]) heap_pop(GH, &gsize, 1);
            if (gsize > 0) {
                int i = heap_pop(GH, &gsize, 1);
                SOLD[i] = 1;
                total += PR[i];
            }
        } else if (uj <= T) {
            /* decided customer: min price among objects of type uj */
            int lo = start[uj];
            int size = cnt[uj];
            while (size > 0 && SOLD[H[lo]]) heap_pop(H + lo, &size, 0);
            if (size > 0) {
                int i = heap_pop(H + lo, &size, 0);
                SOLD[i] = 1;
                total += PR[i];
            }
            cnt[uj] = size;
        }
    }

    printf("%lld\n", total);

    free(t); free(p); free(cnt); free(start);
    free(PR); free(TP); free(SOLD);
    free(fill); free(H); free(GH);
    return 0;
}
